"""Fast Monte Carlo fire-spread simulator (numba) with common random numbers generated by a counter-based hash (no stored random arrays): uniform(r, t, e, stream) is a deterministic function, so every plan is evaluated on exactly the same realisations. Model identical to realcase.Domain.run: each day, every burned cell i ignites each unburned neighbour j independently with probability q[t, e] * (1 - eta * protected_t[j]); burned cells stay active."""
import numpy as np, numba as nb

@nb.njit(inline='always')
def _u01(r, t, e, stream):
    x = np.uint64(stream) * np.uint64(0x9E3779B97F4A7C15) ^ np.uint64(r) * np.uint64(0xBF58476D1CE4E5B9) \
        ^ np.uint64(t) * np.uint64(0x94D049BB133111EB) ^ np.uint64(e) * np.uint64(0xD6E8FEB86659FD93)
    x ^= x >> np.uint64(30); x *= np.uint64(0xBF58476D1CE4E5B9)
    x ^= x >> np.uint64(27); x *= np.uint64(0x94D049BB133111EB)
    x ^= x >> np.uint64(31)
    return (x >> np.uint64(11)) * (1.0 / 9007199254740992.0)

@nb.njit(parallel=True, cache=True)
def _sim(src, dst, q, burned0, value, prot_day, eta, R, stream, out_loss, out_freq):
    H, E = q.shape; n = burned0.shape[0]
    freq = np.zeros((R, n), np.uint8)
    for r in nb.prange(R):
        b = burned0.copy(); nb_ = np.zeros(n, np.uint8)
        for t in range(H):
            for k in range(n): nb_[k] = 0
            for e in range(E):
                i = src[e]; j = dst[e]
                if b[i] and not b[j]:
                    p = q[t, e]
                    p = p * (1.0 - prot_day[t, j])
                    if _u01(r, t, e, stream) < p: nb_[j] = 1
            for k in range(n):
                if nb_[k]: b[k] = 1
        L = 0.0
        for k in range(n):
            if b[k] and not burned0[k]:
                L += value[k]; freq[r, k] = 1
        out_loss[r] = L
    for r in range(R):
        for k in range(n): out_freq[k] += freq[r, k]

class Sim:
    def __init__(s, D, eta=0.85):
        s.src = D.src.astype(np.int64); s.dst = D.dst.astype(np.int64); s.q = np.ascontiguousarray(D.q, dtype=np.float64)
        s.b0 = D.burned0.astype(np.uint8); s.v = D.value.astype(np.float64); s.n = D.n; s.H = D.q.shape[0]; s.eta = eta
    def losses(s, prot_sets, R, stream, eta=None):
        """prot_sets: list over days of iterables of protected local cells (missing days: unprotected);
        or a single set -> persistent over the whole horizon. Returns per-realisation loss and burn freq."""
        e = s.eta if eta is None else eta
        ev = np.broadcast_to(np.asarray(e, float), (s.H,))
        P = np.zeros((s.H, s.n), np.float64)
        if isinstance(prot_sets, (set, frozenset, np.ndarray)) or (len(prot_sets) and np.isscalar(prot_sets[0])):
            idx = np.fromiter(prot_sets, np.int64) if not isinstance(prot_sets, np.ndarray) else prot_sets.astype(np.int64)
            P[:, idx] = ev[:, None]
        else:
            for t, S in enumerate(prot_sets[:s.H]):
                if len(S): P[t, np.fromiter(S, np.int64)] = ev[t]
        L = np.zeros(R); F = np.zeros(s.n, np.int64)
        _sim(s.src, s.dst, s.q, s.b0, s.v, P, 0.0, R, stream, L, F)
        return L, F / R
    def loss(s, prot, R=300, stream=1, eta=None):
        return float(s.losses(prot, R, stream, eta)[0].mean())
